import * as openpgp from 'openpgp';

// Генерация ключей
export const generateKeys = async () => {
  const { privateKey, publicKey } = await openpgp.generateKey({
    userIDs: [{ name: 'Anonymous' }],
    curve: 'ed25519',
  });
  return { privateKey, publicKey };
};

// Шифрование сообщения
export const encryptMessage = async (message, publicKey) => {
  const encrypted = await openpgp.encrypt({
    message: await openpgp.createMessage({ text: message }),
    encryptionKeys: await openpgp.readKey({ armoredKey: publicKey }),
  });
  return encrypted;
};

// Расшифровка сообщения
export const decryptMessage = async (encryptedMessage, privateKey) => {
  const decrypted = await openpgp.decrypt({
    message: await openpgp.readMessage({ armoredMessage: encryptedMessage }),
    decryptionKeys: await openpgp.readPrivateKey({ armoredKey: privateKey }),
  });
  return decrypted.data;
};
// Функция для сохранения приватного ключа в IndexedDB
export const storePrivateKey = async (privateKey) => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('KeysDB', 1);

    // Создание базы данных, если она ещё не существует
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains('privateKeys')) {
        db.createObjectStore('privateKeys', { keyPath: 'id' });
      }
    };

    request.onsuccess = (event) => {
      const db = event.target.result;
      const transaction = db.transaction(['privateKeys'], 'readwrite');
      const store = transaction.objectStore('privateKeys');

      // Добавляем или обновляем запись с приватным ключом
      const putRequest = store.put({ id: 'userPrivateKey', privateKey });

      putRequest.onsuccess = () => {
        resolve(); // Успешное завершение операции
      };

      putRequest.onerror = (err) => {
        reject(err); // Ошибка при записи
      };
    };

    request.onerror = (err) => {
      reject(err); // Ошибка открытия базы данных
    };
  });
};

// Функция для извлечения приватного ключа из IndexedDB
export const retrievePrivateKey = async () => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('KeysDB', 1);

    request.onsuccess = (event) => {
      const db = event.target.result;
      const transaction = db.transaction(['privateKeys'], 'readonly');
      const store = transaction.objectStore('privateKeys');

      const getRequest = store.get('userPrivateKey');

      getRequest.onsuccess = () => {
        if (getRequest.result) {
          resolve(getRequest.result.privateKey);
        } else {
          resolve(null); // Если ключ не найден
        }
      };

      getRequest.onerror = (err) => {
        reject(err); // Ошибка при извлечении данных
      };
    };

    request.onerror = (err) => {
      reject(err); // Ошибка открытия базы данных
    };
  });
};
